using System;
using System.Collections.Generic;
using System.Linq;
using UnityEditor;
using UnityEngine;

namespace HienaDev.DevTools
{
    /// <summary>Bricks, planks, tiles, stones and so on from sliders, with their real height. They always loop.</summary>
    public static class TexturePatterns
    {
        public class Knob { public string name, tip; public float lo, hi, def; public bool whole; public Knob(string n, float lo, float hi, float def, bool whole = false, string tip = "") { name = n; this.lo = lo; this.hi = hi; this.def = def; this.whole = whole; this.tip = tip; } }
        public class Kind { public string name, about; public Color tint; public Knob[] knobs; public (string name, Color c)[] colours; public (string name, float[] v, Color[] c)[] ready; public Func<float[], Color[], int, Func<float, float, (Color c, float h)>> make; }
        public class Result { public Pixels colour, height; }

        // ------------------------------------------------------------------ pieces
        static float H(int x, int y, int s) { unchecked { uint h = (uint)(x * 374761393 + y * 668265263 + s * 144269504); h = (h ^ (h >> 13)) * 1274126177u; h ^= h >> 16; return (h & 0xFFFFFF) / 16777215f; } }
        static int W(int v, int n) { v %= n; return v < 0 ? v + n : v; }
        static float Sm(float a, float b, float x) { float t = Mathf.Clamp01((x - a) / (b - a)); return t * t * (3 - 2 * t); }
        static TextureOps.TileNoise N(int seed, int p) => new TextureOps.TileNoise(seed, p);
        static Color Mul(Color c, float k) => new Color(c.r * k, c.g * k, c.b * k, 1);
        static Color Mix(Color a, Color b, float t) => Color.Lerp(a, b, Mathf.Clamp01(t));
        // the nearest two points of a jittered grid: distance, the edge between them, which one
        static void Cells(float px, float py, int n, int ny, float jitter, int seed, out float d1, out float edge, out int id, out Vector2 to)
        {
            int cx = Mathf.FloorToInt(px), cy = Mathf.FloorToInt(py); d1 = 99; id = 0; to = Vector2.zero; Vector2 best = Vector2.zero; int bi = 0, bj = 0;
            for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) { int x = W(cx + i, n), y = W(cy + j, ny); var q = new Vector2(cx + i + 0.5f + (H(x, y, seed) - 0.5f) * jitter - px, cy + j + 0.5f + (H(x, y, seed + 7) - 0.5f) * jitter - py); float d = q.sqrMagnitude; if (d < d1) { d1 = d; best = q; bi = i; bj = j; id = x * 73 + y * 1009; } }
            edge = 99; for (int j = -2; j <= 2; j++) for (int i = -2; i <= 2; i++) { int x = W(cx + bi + i, n), y = W(cy + bj + j, ny); var q = new Vector2(cx + bi + i + 0.5f + (H(x, y, seed) - 0.5f) * jitter - px, cy + bj + j + 0.5f + (H(x, y, seed + 7) - 0.5f) * jitter - py); var df = q - best; if (df.sqrMagnitude > 1e-5f) edge = Mathf.Min(edge, Vector2.Dot((best + q) * 0.5f, df.normalized)); }
            d1 = Mathf.Sqrt(d1); to = best;
        }

        // ------------------------------------------------------------------ the kinds

        // 0 rows 1 across 2 shift 3 gap 4 rounded 5 rough 6 different 7 chips 8 dirt
        static Func<float, float, (Color, float)> Bricks(float[] k, Color[] c, int s)
        {
            int rows = Mathf.RoundToInt(k[0]), across = Mathf.RoundToInt(k[1]); var fine = N(s + 1, 48); var mid = N(s + 2, 14); var big = N(s + 3, 4); float gapY = k[3] * 0.5f, gapX = gapY * across / rows;
            return (u, v) =>
            {
                float y = v * rows; int r = Mathf.FloorToInt(y); float x = u * across + (W(r, rows) % 2) * k[2]; int b = Mathf.FloorToInt(x); float fx = x - b, fy = y - r; int bx = W(b, across), by = W(r, rows); float f = fine.Fbm(u, v), m = mid.Fbm(u, v), chip = (m - 0.5f) * 0.12f * k[7] + (f - 0.5f) * 0.05f * k[7];
                float dx = Mathf.Min(fx, 1 - fx) * rows / (float)across, dy = Mathf.Min(fy, 1 - fy), d = Mathf.Min(dx - gapY * rows * 0 - gapX * 0, dy); float cut = k[3] * 0.5f + chip, rd = 0.02f + k[4] * 0.25f; float inside = Sm(cut, cut + 0.03f, Mathf.Min(dx, dy)); float ex = Mathf.Max(0, cut + rd - dx), ey = Mathf.Max(0, cut + rd - dy), round = 1 - Mathf.Clamp01(Mathf.Sqrt(ex * ex + ey * ey) / rd);
                float one = H(bx, by, s), two = H(bx, by, s + 5), hgt = 0.25f + 0.55f * Mathf.Sqrt(Mathf.Clamp01(round)) + (two - 0.5f) * 0.16f * k[6] + (f - 0.5f) * 0.22f * k[5]; var col = Mix(c[0], c[1], Mathf.Clamp01(0.5f + (one - 0.5f) * 2 * k[6])); col = Mul(col, 1 + (m - 0.5f) * 0.45f * k[5] + (f - 0.5f) * 0.5f * k[5] + (two - 0.5f) * 0.3f * k[6]); var mort = Mul(c[2], 0.85f + 0.3f * f); float h = Mathf.Lerp(0.16f + 0.08f * f, hgt, inside); var o = Mix(mort, col, inside); float di = k[8] * Mathf.Clamp01(big.Fbm(u, v) * 1.8f - 0.55f + (1 - inside) * 0.3f); return (Mix(o, Mul(c[3], 0.8f + 0.4f * f), di), h);
            };
        }

        // 0 stones 1 gap 2 rounded 3 rough 4 different 5 irregular 6 dirt
        static Func<float, float, (Color, float)> Stones(float[] k, Color[] c, int s)
        {
            int n = Mathf.RoundToInt(k[0]); var fine = N(s + 1, 50); var mid = N(s + 2, 12); var big = N(s + 3, 4);
            return (u, v) => { float f = fine.Fbm(u, v), m = mid.Fbm(u, v); float px = u * n + (m - 0.5f) * 0.3f, py = v * n + (mid.Fbm(v, u) - 0.5f) * 0.3f; Cells(px, py, n, n, 0.3f + k[5] * 0.65f, s, out float d, out float e, out int id, out var to); float one = H(id, 1, s), two = H(id, 2, s), g = k[1] * 0.3f; float inside = Sm(g, g + 0.05f, e + (f - 0.5f) * 0.05f), round = Mathf.Clamp01((e - g) / (0.04f + k[2] * 0.34f)); float tilt = (to.x * (one - 0.5f) + to.y * (two - 0.5f)) * 0.5f * k[4]; float h = Mathf.Lerp(0.12f + 0.08f * f, 0.3f + 0.5f * Mathf.Sqrt(round) + (one - 0.5f) * 0.18f * k[4] + tilt * 0.3f + (f - 0.5f) * 0.25f * k[3] + (m - 0.5f) * 0.15f * k[3], inside); var col = Mul(Mix(c[0], c[1], 0.5f + (two - 0.5f) * 2 * k[4]), 1 + (f - 0.5f) * 0.6f * k[3] + (m - 0.5f) * 0.4f * k[3] + (one - 0.5f) * 0.3f * k[4]); var o = Mix(Mul(c[2], 0.8f + 0.4f * f), col, inside); float di = k[6] * Mathf.Clamp01(big.Fbm(u, v) * 1.6f - 0.5f + (1 - round) * 0.45f); return (Mix(o, Mul(c[3], 0.75f + 0.5f * f), di), h); };
        }

        // 0 planks 1 pieces long 2 gap 3 grain 4 knots 5 different 6 nails 7 worn
        static Func<float, float, (Color, float)> Planks(float[] k, Color[] c, int s)
        {
            int n = Mathf.RoundToInt(k[0]), pieces = Mathf.RoundToInt(k[1]); var g1 = N(s + 1, 6); var fine = N(s + 2, 64); var wear = N(s + 3, 5);
            return (u, v) =>
            {
                float x = u * n; int p = W(Mathf.FloorToInt(x), n); float fx = x - Mathf.Floor(x), off = H(p, 0, s), y = v * pieces + off; int q = W(Mathf.FloorToInt(y), pieces); float fy = y - Mathf.Floor(y); float one = H(p, q, s + 3), two = H(p, q, s + 4), g = k[2] * 0.5f; float dx = Mathf.Min(fx, 1 - fx), dy = Mathf.Min(fy, 1 - fy) * n / (float)pieces * 1f; float inside = Sm(g, g + 0.03f, dx) * Sm(g * 0.8f, g * 0.8f + 0.03f, dy);
                // the grain runs along it, bending round the knots
                float kx = 0.25f + 0.5f * H(p, q, s + 9), ky = 0.2f + 0.6f * H(p, q, s + 10), kd = new Vector2((fx - kx) * 1f, (fy - ky) * n / (float)pieces * 0.8f).magnitude; bool knot = H(p, q, s + 11) < k[4]; float bend = knot ? Mathf.Exp(-kd * kd * 30) : 0, warp = g1.Fbm(u + one * 0.37f, v * 0.5f + two) - 0.5f; float rings = fx * 7f + warp * 5f + bend * 3f * Mathf.Sign(fx - kx); float gr = 0.5f + 0.5f * Mathf.Sin(rings * 6.2832f * 0.9f + two * 9), f = fine.Fbm(u * 1f, v * 0.125f); gr = Mathf.Lerp(0.5f, gr * 0.6f + f * 0.4f, k[3]);
                var col = Mix(c[0], c[1], 0.5f + (one - 0.5f) * 1.6f * k[5] + (0.5f - gr) * 0.9f); col = Mul(col, 1 + (f - 0.5f) * 0.4f * k[3] + (two - 0.5f) * 0.35f * k[5]); if (knot) col = Mix(col, Mul(c[1], 0.45f), Sm(0.13f, 0.02f, kd)); float h = 0.62f + (two - 0.5f) * 0.14f * k[5] - (0.5f - gr) * 0.16f * k[3] - (1 - Sm(g, g + 0.1f, dx)) * 0.12f; float nail = 0; if (k[6] > 0.05f) { float nd = Mathf.Min(new Vector2((fx - 0.2f), (Mathf.Min(fy, 1 - fy) - 0.06f) * n / (float)pieces).magnitude, new Vector2((fx - 0.8f), (Mathf.Min(fy, 1 - fy) - 0.06f) * n / (float)pieces).magnitude); nail = Sm(0.02f + 0.04f * k[6], 0.01f + 0.03f * k[6], nd); col = Mix(col, new Color(0.16f, 0.15f, 0.15f), nail); h -= nail * 0.1f; }
                float we = k[7] * Mathf.Clamp01(wear.Fbm(u, v) * 2f - 0.6f); col = Mix(col, Mul(c[2], 0.85f + 0.3f * f), we * 0.8f); return (Mix(Mul(c[1], 0.18f), col, inside), Mathf.Lerp(0.1f, h, inside));
            };
        }

        // 0 across 1 down 2 grout 3 rounded 4 different 5 checks 6 cracks 7 marble 8 dirt
        static Func<float, float, (Color, float)> Tiles(float[] k, Color[] c, int s)
        {
            int n = Mathf.RoundToInt(k[0]), ny = Mathf.RoundToInt(k[1]); var fine = N(s + 1, 60); var mid = N(s + 2, 6); var big = N(s + 3, 3);
            return (u, v) => { float x = u * n, y = v * ny; int ix = W(Mathf.FloorToInt(x), n), iy = W(Mathf.FloorToInt(y), ny); float fx = x - Mathf.Floor(x), fy = y - Mathf.Floor(y), dx = Mathf.Min(fx, 1 - fx), dy = Mathf.Min(fy, 1 - fy) * n / (float)ny, d = Mathf.Min(dx, dy), g = k[2] * 0.25f, inside = Sm(g, g + 0.015f, d), rd = 0.01f + k[3] * 0.15f, round = Mathf.Clamp01((d - g) / rd); float one = H(ix, iy, s), two = H(ix, iy, s + 5), f = fine.Fbm(u, v); bool alt = (ix + iy) % 2 == 1 && k[5] > 0.01f; var col = alt ? Mix(c[0], c[1], k[5]) : c[0]; float mar = mid.Fbm(u + one * 0.31f, v + two * 0.23f); float vein = 1 - Mathf.Abs(Mathf.Sin((fx * 0.7f + fy * 0.5f + mar * 2.2f + fine.Fbm(v, u) * 0.12f + one * 9) * 3.1f)); vein = Mathf.Pow(vein, 9) * Mathf.Clamp01(mid.Fbm(v + one, u) * 2.2f - 0.6f); col = Mix(col, Mul(c[3], 1f), vein * k[7] * 0.7f); col = Mul(col, 1 + (one - 0.5f) * 0.35f * k[4] + (f - 0.5f) * 0.08f); float h = 0.55f + 0.2f * Mathf.Sqrt(round) + (two - 0.5f) * 0.08f * k[4]; float cr = 0; if (H(ix, iy, s + 8) < k[6]) { float t = (fx - 0.5f) * (two - 0.5f) * 2 + (fy - 0.5f) * (one > 0.5f ? 1 : -1) * 0.8f + (mar - 0.5f) * 0.9f; cr = Sm(0.018f, 0.004f, Mathf.Abs(t)); col = Mul(col, 1 - cr * 0.7f); h -= cr * 0.25f; } var o = Mix(Mul(c[2], 0.85f + 0.3f * f), col, inside); float di = k[8] * Mathf.Clamp01(big.Fbm(u, v) * 1.6f - 0.5f + (1 - inside) * 0.5f); return (Mix(o, Mul(c[4], 0.8f + 0.4f * f), di * 0.85f), Mathf.Lerp(0.35f + 0.06f * f, h, inside)); };
        }

        // 0 across 1 gap 2 rounded 3 different 4 rough
        static Func<float, float, (Color, float)> Hexes(float[] k, Color[] c, int s)
        {
            int n = Mathf.RoundToInt(k[0]), ny = Mathf.Max(2, Mathf.RoundToInt(n / 1.732f) * 2); var fine = N(s + 1, 50);
            return (u, v) => { float px = u * n, py = v * ny; float b = 9, sc = 9; int bx = 0, by = 0; int cy = Mathf.FloorToInt(py); for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) { int ry = cy + j; float off = (ry & 1) == 0 ? 0.25f : 0.75f, dx = px - (Mathf.Floor(px) + i + off), dy = (py - (ry + 0.5f)) * 0.866f, d = Mathf.Sqrt(dx * dx + dy * dy); if (d < b) { sc = b; b = d; bx = Mathf.FloorToInt(px) + i; by = ry; } else if (d < sc) sc = d; } float e = (sc - b) * 0.5f, f = fine.Fbm(u, v), one = H(W(bx, n), W(by, ny), s), g = k[1] * 0.12f, inside = Sm(g, g + 0.02f, e), round = Mathf.Clamp01((e - g) / (0.01f + k[2] * 0.2f)); var col = Mul(Mix(c[0], c[1], one * k[3]), 1 + (f - 0.5f) * 0.5f * k[4]); return (Mix(c[2], col, inside), Mathf.Lerp(0.25f, 0.5f + 0.25f * Mathf.Sqrt(round) + (one - 0.5f) * 0.1f * k[3] + (f - 0.5f) * 0.15f * k[4], inside)); };
        }

        // 0 rows 1 across 2 round end 3 different 4 rough 5 moss
        static Func<float, float, (Color, float)> Roof(float[] k, Color[] c, int s)
        {
            int rows = Mathf.RoundToInt(k[0]) / 2 * 2, across = Mathf.RoundToInt(k[1]); var fine = N(s + 1, 50); var big = N(s + 2, 5);
            return (u, v) =>
            {
                float f = fine.Fbm(u, v); (Color, float) best = (Mul(c[2], 0.5f), 0.1f); float y = v * rows;
                // the lower rows lie on top of the ones above
                for (int j = 0; j <= 1; j++) { int r = Mathf.FloorToInt(y) + j; float fy = y - r + 1; float x = u * across + (W(r, rows) % 2) * 0.5f; int b = Mathf.FloorToInt(x); float fx = x - b; int bx = W(b, across), by = W(r, rows); float one = H(bx, by, s), two = H(bx, by, s + 3); float end = 0.1f * two * k[3] + (1 - Mathf.Sqrt(Mathf.Max(0, 1 - Mathf.Pow(Mathf.Abs(fx * 2 - 1), 2)))) * 0.5f * k[2]; float low = fy - end; if (low < 0 || fy > 2) continue; float side = Mathf.Min(fx, 1 - fx); if (side < 0.015f) continue; float h = 0.75f - fy * 0.28f + (one - 0.5f) * 0.1f * k[3] + (f - 0.5f) * 0.14f * k[4] - (1 - Sm(0.015f, 0.08f, side)) * 0.1f; var col = Mul(Mix(c[0], c[1], 0.5f + (one - 0.5f) * 2 * k[3]), 1 + (f - 0.5f) * 0.6f * k[4] + (two - 0.5f) * 0.25f * k[3]); col = Mul(col, 0.72f + 0.28f * Sm(0, 0.12f, low)); if (h > best.Item2) best = (col, h); }
                float mo = k[5] * Mathf.Clamp01(big.Fbm(u, v) * 2.2f - 0.85f + (0.5f - best.Item2) * 0.6f); return (Mix(best.Item1, Mul(c[2], 0.6f + 0.7f * f), mo), best.Item2 + mo * 0.05f);
            };
        }

        // 0 plates across 1 gap 2 rivets 3 scratches 4 rust 5 different 6 split
        static Func<float, float, (Color, float)> Metal(float[] k, Color[] c, int s)
        {
            int n = Mathf.RoundToInt(k[0]); var fine = N(s + 1, 64); var mid = N(s + 2, 10); var big = N(s + 3, 5);
            return (u, v) =>
            {
                float x = u * n, y = v * n; int ix = W(Mathf.FloorToInt(x), n), iy = W(Mathf.FloorToInt(y), n); float fx = x - Mathf.Floor(x), fy = y - Mathf.Floor(y); float sx = 1, sy = 1; float sp = H(ix, iy, s + 1); if (sp < k[6] * 0.5f) { sx = 2; fx *= 2; ix = ix * 2 + (int)fx; fx -= Mathf.Floor(fx); } else if (sp < k[6]) { sy = 2; fy *= 2; iy = iy * 2 + (int)fy; fy -= Mathf.Floor(fy); }
                float dx = Mathf.Min(fx, 1 - fx) / sx, dy = Mathf.Min(fy, 1 - fy) / sy, d = Mathf.Min(dx, dy), g = k[1] * 0.06f, inside = Sm(g, g + 0.012f, d), bev = Mathf.Clamp01((d - g) / 0.04f), one = H(ix, iy, s), f = fine.Fbm(u, v), m = mid.Fbm(u, v), b = big.Fbm(u, v); var col = Mul(Mix(c[0], c[1], one * k[5]), 0.92f + 0.16f * f + (m - 0.5f) * 0.12f); float h = 0.5f + 0.16f * bev; float scr = Sm(0.985f, 1f, Mathf.Sin((u * 37 + v * 11 + m * 3) * 6.2832f) * 0.5f + 0.5f) * Sm(0.55f, 0.7f, N(s + 9, 6).Fbm(v, u)); col = Mul(col, 1 + scr * 0.7f * k[3]); h -= scr * 0.04f * k[3];
                float riv = 0; if (k[2] > 0.05f) { float a = 0.075f; float qx = Mathf.Min(fx, 1 - fx) / sx - a, qy = Mathf.Min(fy, 1 - fy) / sy - a; float alongX = Mathf.Abs((fx / sx * 4) % 1f - 0.5f) / 4, alongY = Mathf.Abs((fy / sy * 4) % 1f - 0.5f) / 4; float rd = Mathf.Min(new Vector2(qx, alongY).magnitude, new Vector2(alongX, qy).magnitude), rs = 0.012f + 0.016f * k[2]; riv = Mathf.Sqrt(Mathf.Clamp01(1 - rd / rs)); h += riv * 0.18f; col = Mul(col, 1 - Sm(rs * 1.5f, rs, rd) * 0.15f + riv * 0.2f); }
                float ru = k[4] * Mathf.Clamp01(b * 1.9f - 0.75f + (1 - bev) * 0.35f + (m - 0.5f) * 0.7f); col = Mix(col, Mul(Mix(c[2], Mul(c[2], 0.45f), f), 0.8f + 0.5f * m), Sm(0.12f, 0.4f, ru)); h -= Sm(0.12f, 0.4f, ru) * 0.05f * f; return (Mix(Mul(c[0], 0.15f), col, inside), Mathf.Lerp(0.2f, h, inside));
            };
        }

        // 0 rough 1 stains 2 cracks 3 holes 4 boards
        static Func<float, float, (Color, float)> Concrete(float[] k, Color[] c, int s)
        {
            var fine = N(s + 1, 70); var mid = N(s + 2, 16); var big = N(s + 3, 4); var w1 = N(s + 4, 9); var w2 = N(s + 5, 9); int boards = Mathf.RoundToInt(k[4] * 8);
            return (u, v) => { float f = fine.Fbm(u, v), m = mid.Fbm(u, v), b = big.Fbm(u, v); var col = Mul(Mix(c[0], c[1], Mathf.Clamp01(b * 1.8f - 0.4f) * k[1]), 1 + (f - 0.5f) * 0.3f * k[0] + (m - 0.5f) * 0.3f * k[0]); float h = 0.6f + (f - 0.5f) * 0.12f * k[0] + (m - 0.5f) * 0.2f * k[0]; Cells(u * 4 + (w1.Fbm(u, v) - 0.5f) * 1.3f, v * 4 + (w2.Fbm(u, v) - 0.5f) * 1.3f, 4, 4, 0.9f, s, out _, out float e, out int id, out _); float keep = Sm(0.5f, 0.6f, N(s + 8, 3).Fbm(u, v) + k[2] * 0.4f - 0.2f); float cr = Sm(0.018f, 0.003f, e + (f - 0.5f) * 0.01f) * keep * (k[2] > 0.01f ? 1 : 0); col = Mul(col, 1 - cr * 0.65f); h -= cr * 0.3f; int n = 26; int cx = Mathf.FloorToInt(u * n), cy = Mathf.FloorToInt(v * n); if (H(cx, cy, s + 6) < k[3] * 0.5f) { float hd = new Vector2(u * n - cx - 0.5f - (H(cx, cy, s) - 0.5f) * 0.4f, v * n - cy - 0.5f).magnitude, hs = 0.06f + 0.2f * H(cx, cy, s + 9); float ho = Sm(hs, hs * 0.5f, hd); col = Mul(col, 1 - ho * 0.45f); h -= ho * 0.22f; } if (boards > 0) { float y = v * boards; float l = Mathf.Min(y - Mathf.Floor(y), Mathf.Ceil(y) - y), li = Sm(0.02f, 0.006f, l); col = Mul(col, 1 - li * 0.35f + (H(Mathf.FloorToInt(y), 3, s) - 0.5f) * 0.1f); h -= li * 0.14f; } return (col, h); };
        }

        // 0 pebbles 1 pebble size 2 rough 3 different 4 wet
        static Func<float, float, (Color, float)> Ground(float[] k, Color[] c, int s)
        {
            var fine = N(s + 1, 60); var mid = N(s + 2, 14); var big = N(s + 3, 4); int n = Mathf.RoundToInt(Mathf.Lerp(34, 7, k[1]));
