        public static Result Make(int kind, float[] v, Color[] c, int seed, int size)
        {
            var k = Kinds[kind]; var f = k.make(v, c, seed); var r = new Result { colour = new Pixels(size, size), height = new Pixels(size, size, false) }; int ss = size <= 512 ? 2 : 1;
            TextureOps.Rows(size, y => { for (int x = 0; x < size; x++) { Color a = Color.clear; float h = 0; for (int j = 0; j < ss; j++) for (int i = 0; i < ss; i++) { var q = f((x + (i + 0.5f) / ss) / size, (y + (j + 0.5f) / ss) / size); a += q.c; h += q.h; } float n = ss * ss; a /= n; h = Mathf.Clamp01(h / n); r.colour.c[y * size + x] = new Color(Mathf.Clamp01(a.r), Mathf.Clamp01(a.g), Mathf.Clamp01(a.b), 1); r.height.c[y * size + x] = new Color(h, h, h, 1); } });
            return r;
        }
    }

