        Texture2D SavePattern(string folder, bool all)
        {
            var name = TextureShelf.Clean(m_PatName); if (name.Length == 0) name = PatK.name; if (!AssetDatabase.IsValidFolder(folder)) AssetDatabase.CreateFolder(System.IO.Path.GetDirectoryName(folder).Replace('\\', '/'), System.IO.Path.GetFileName(folder)); var dir = folder + "/" + name; string b = name; if (all) { for (int n = 2; AssetDatabase.IsValidFolder(dir); n++) { name = b + " " + n; dir = folder + "/" + name; } AssetDatabase.CreateFolder(folder, name); } else { dir = folder; for (int n = 2; System.IO.File.Exists(dir + "/" + name + ".png"); n++) name = b + " " + n; } // (never over something that's there)
            EditorUtility.DisplayProgressBar("Texture Studio", "Making " + name + "...", 0.4f); try
            {
                var r = TexturePatterns.Make(m_PatKind, m_PatVals.ToArray(), m_PatCols.ToArray(), m_PatSeed, m_PatSize); var t = Pixels.SaveAt(r.colour, dir + "/" + name + ".png", null, false, false); if (!all) { EditorGUIUtility.PingObject(t); return t; }
                float scale = m_PatSize / 384f; var n = Pixels.SaveAt(TextureOps.NormalFromHeight(r.height, m_PatBumps * Mathf.Max(0.5f, scale), 0.25f, false, false), dir + "/" + name + "_Normal.png", null, true, false); var h = Pixels.SaveAt(r.height, dir + "/" + name + "_Height.png", null, false, false); var m = Pixels.SaveAt(TextureOpsMore.MaskMap(r.height, 1f, m_PatShine, 0), dir + "/" + name + "_Mask.png", null, false, false); var mat = TextureMaterials.Make(dir + "/" + name + ".mat", t, n, m, h, null, null); AssetDatabase.SaveAssetIfDirty(mat); EditorGUIUtility.PingObject(mat); ShowNotification(new GUIContent("Saved in " + dir)); return t;
            }
            finally { EditorUtility.ClearProgressBar(); }
